-- 只读统计当前SQL Server有效集合及Uid指纹；不导入、不排除或修改原数据。
SELECT 'ProductDetails' source_table,'product_detail' target_table,COUNT_BIG(*) candidate_rows,LOWER(CONVERT(varchar(32),HASHBYTES('MD5',STRING_AGG(CONVERT(varchar(max),LOWER(CONVERT(varchar(36),d.Uid))),CHAR(10)) WITHIN GROUP(ORDER BY LOWER(CONVERT(varchar(36),d.Uid)) COLLATE Latin1_General_100_BIN2)),2)) uid_set_md5 FROM dbo.ProductDetails d WHERE d.IsDeleted=0 AND EXISTS(SELECT 1 FROM dbo.Product p WHERE p.Uid=d.ProductId AND p.IsDeleted=0 AND p.IsActive=1) UNION ALL SELECT 'CustomerProduct' source_table,'customer_product' target_table,COUNT_BIG(*) candidate_rows,LOWER(CONVERT(varchar(32),HASHBYTES('MD5',STRING_AGG(CONVERT(varchar(max),LOWER(CONVERT(varchar(36),d.Uid))),CHAR(10)) WITHIN GROUP(ORDER BY LOWER(CONVERT(varchar(36),d.Uid)) COLLATE Latin1_General_100_BIN2)),2)) uid_set_md5 FROM dbo.CustomerProduct d WHERE d.IsDeleted=0 AND d.IsActive=1 AND EXISTS(SELECT 1 FROM dbo.Customer c WHERE c.Uid=d.CustomerId AND c.IsDeleted=0 AND c.IsActive=1) AND(d.SkuId IS NULL OR EXISTS(SELECT 1 FROM dbo.Product p WHERE p.Uid=d.SkuId AND p.IsDeleted=0 AND p.IsActive=1)) UNION ALL SELECT 'CustomerPoConfig' source_table,'customer_po_config' target_table,COUNT_BIG(*) candidate_rows,LOWER(CONVERT(varchar(32),HASHBYTES('MD5',STRING_AGG(CONVERT(varchar(max),LOWER(CONVERT(varchar(36),d.Uid))),CHAR(10)) WITHIN GROUP(ORDER BY LOWER(CONVERT(varchar(36),d.Uid)) COLLATE Latin1_General_100_BIN2)),2)) uid_set_md5 FROM dbo.CustomerPoConfig d WHERE d.IsDeleted=0 AND(d.CustomerId IS NULL OR EXISTS(SELECT 1 FROM dbo.Customer c WHERE c.Uid=d.CustomerId AND c.IsDeleted=0 AND c.IsActive=1)) AND(d.SupplierId IS NULL OR EXISTS(SELECT 1 FROM dbo.Supplier s WHERE s.Uid=d.SupplierId AND s.IsDeleted=0 AND s.IsActive=1)) UNION ALL SELECT 'Bom' source_table,'bom' target_table,COUNT_BIG(*) candidate_rows,LOWER(CONVERT(varchar(32),HASHBYTES('MD5',STRING_AGG(CONVERT(varchar(max),LOWER(CONVERT(varchar(36),d.Uid))),CHAR(10)) WITHIN GROUP(ORDER BY LOWER(CONVERT(varchar(36),d.Uid)) COLLATE Latin1_General_100_BIN2)),2)) uid_set_md5 FROM dbo.Bom d WHERE d.IsDeleted=0 AND EXISTS(SELECT 1 FROM dbo.Product p WHERE p.Uid=d.ParentProductId AND p.IsDeleted=0 AND p.IsActive=1) AND EXISTS(SELECT 1 FROM dbo.Product p WHERE p.Uid=d.ComponentProductId AND p.IsDeleted=0 AND p.IsActive=1) UNION ALL SELECT 'ProductNeutral' source_table,'product_neutral' target_table,COUNT_BIG(*) candidate_rows,LOWER(CONVERT(varchar(32),HASHBYTES('MD5',STRING_AGG(CONVERT(varchar(max),LOWER(CONVERT(varchar(36),d.Uid))),CHAR(10)) WITHIN GROUP(ORDER BY LOWER(CONVERT(varchar(36),d.Uid)) COLLATE Latin1_General_100_BIN2)),2)) uid_set_md5 FROM dbo.ProductNeutral d WHERE d.IsDeleted=0 AND EXISTS(SELECT 1 FROM dbo.ProductMaster m WHERE m.Uid=d.ProductMasterId AND m.IsDeleted=0) AND EXISTS(SELECT 1 FROM dbo.ProductColor c WHERE c.Uid=d.ColorId AND c.IsDeleted=0) UNION ALL SELECT 'ExcelReadProfile' source_table,'excel_read_profile' target_table,COUNT_BIG(*) candidate_rows,LOWER(CONVERT(varchar(32),HASHBYTES('MD5',STRING_AGG(CONVERT(varchar(max),LOWER(CONVERT(varchar(36),d.Uid))),CHAR(10)) WITHIN GROUP(ORDER BY LOWER(CONVERT(varchar(36),d.Uid)) COLLATE Latin1_General_100_BIN2)),2)) uid_set_md5 FROM dbo.ExcelReadProfile d WHERE d.IsDeleted=0 UNION ALL SELECT 'ExcelReadField' source_table,'excel_read_field' target_table,COUNT_BIG(*) candidate_rows,LOWER(CONVERT(varchar(32),HASHBYTES('MD5',STRING_AGG(CONVERT(varchar(max),LOWER(CONVERT(varchar(36),d.Uid))),CHAR(10)) WITHIN GROUP(ORDER BY LOWER(CONVERT(varchar(36),d.Uid)) COLLATE Latin1_General_100_BIN2)),2)) uid_set_md5 FROM dbo.ExcelReadField d WHERE d.IsDeleted=0 AND EXISTS(SELECT 1 FROM dbo.ExcelReadProfile p WHERE p.Uid=d.ProfileUid AND p.IsDeleted=0) ORDER BY source_table
